function OUT = AF7R58ZZT_R2_ONEFILE_PROCESS_WORKER_RECOVERY_INSTALL()
% AF7R58ZZT-R2
% Fixes the first worker architecture without changing the fixed H=4 s rule.
%
% Root cause fixed:
%   ZZT W1 forced activation at exactly t+dt.  If the process worker missed
%   that grid repeatedly, retries could continue until collision_time<=t+dt,
%   where an assert stopped Flight.
%
% R2:
%   1) setup-time 8-sample full-payload process round-trip calibration;
%   2) activation lead = earliest grid containing
%        [one 25-ms planner budget + measured max IPC round trip];
%   3) no exception when async lead is insufficient;
%   4) one async miss/error/stale result escalates to the already-qualified
%      synchronous path on the next request cycle;
%   5) if async scheduling is already impossible at dispatch, synchronous
%      recovery runs immediately in the same cycle.
%
% Safety:
%   H remains exactly 4 s; no extended preview; generator/certificate math
%   unchanged; stale sensor/dependency/map packets remain reject-only.

PRE_SHA='093e15216f99e9d5a69c9c11151c9b8249e9d45669e77ae60defc4b7310dcb94';
PRE_HELPER_SHA='66211cbfd6e5dc5721de9f3ff164474d840cea20c5338dbcf952c48e9d0cb52d';
POST_SHA='fb4e01fb133fab7d8d9c441d43b3ea68d9c274d20b4837ef56c25b73fd347b90';
POST_HELPER_SHA='6dd47bb6ddf23c33c7888d8765316004abe5e622911be3a904a3c9b6f2d2aaad';

OUT=struct('schema','AF7R58ZZT_R2_PROCESS_WORKER_RECOVERY_V1', ...
    'production_modified',false,'helper_modified',false, ...
    'rollback_performed',false,'pre_sha','','post_sha','', ...
    'pre_helper_sha','','post_helper_sha','', ...
    'status','OPEN','error',struct());

pR=which('REPLANNING_SYSTEM');
assert(~isempty(pR)&&isfile(pR),'[AF7R58ZZT-R2] REPLANNING_SYSTEM unresolved.');
root=fileparts(pR);
pH=fullfile(root,'af7r58zzt_process_worker.m');
assert(isfile(pH),'[AF7R58ZZT-R2] installed worker helper missing.');

outdir=tempname(root);
[ok,msg]=mkdir(outdir); assert(ok,'%s',msg);
report=fullfile(outdir,'AF7R58ZZT_R2_REPORT.txt');
matp=fullfile(outdir,'AF7R58ZZT_R2_OUT.mat');
backupR=fullfile(outdir,'REPLANNING_SYSTEM_PRE_AF7R58ZZT_R2.m');
backupH=fullfile(outdir,'af7r58zzt_process_worker_PRE_AF7R58ZZT_R2.m');

fid=fopen(report,'wt','n','UTF-8'); assert(fid>=0);
cf=onCleanup(@()safe_fclose(fid)); %#ok<NASGU>

say(fid,'====================================================================================================');
say(fid,' AF7R58ZZT-R2 | PROCESS-WORKER RECOVERY INSTALL');
say(fid,'====================================================================================================');
say(fid,'[ROOTCAUSE] oneDtActivationTooAggressive=1 | repeatedMissCouldReachZeroLead=1');
say(fid,'[FIX] measuredIPCLead=1 | ordinaryReturn=1 | synchronousRecovery=1');
say(fid,'[SAFETY] fixedH4s=1 | extendedPreview=0 | staleReject=1 | certificateMathChanged=0');

writeR=false; writeH=false;
try
    pre=file_hash(pR);
    preH=file_hash(pH);
    OUT.pre_sha=pre;
    OUT.pre_helper_sha=preH;
    assert(strcmp(pre,PRE_SHA), ...
        '[AF7R58ZZT-R2] production source is not exact ZZT W1 authority.');
    assert(strcmp(preH,PRE_HELPER_SHA), ...
        '[AF7R58ZZT-R2] helper is not exact ZZT W1 authority.');

    stage=fullfile(outdir,'STAGE');
    [ok,msg]=mkdir(stage); assert(ok,'%s',msg);

