    writeH=true; copyfile(stagedH,pH,'f');

    post=file_hash(pR); postH=file_hash(pH);
    OUT.post_sha=post; OUT.post_helper_sha=postH;
    assert(strcmp(post,POST_SHA));
    assert(strcmp(postH,POST_HELPER_SHA));

    OUT.production_modified=true;
    OUT.helper_modified=true;
    OUT.status='PROCESS_WORKER_R2_RECOVERY_INSTALLED__CLEAN_RERUN_REQUIRED';

    say(fid,'');
    say(fid,'[B. INSTALL]');
    say(fid,' REPLANNING_SYSTEM post SHA = %s',post);
    say(fid,' worker helper post SHA      = %s',postH);
    say(fid,' status = %s',OUT.status);

catch ME
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});
    try
        if writeR && isfile(backupR), copyfile(backupR,pR,'f'); end
        if writeH && isfile(backupH), copyfile(backupH,pH,'f'); end
        OUT.rollback_performed=writeR||writeH;
    catch
    end
    OUT.production_modified=false;
    OUT.helper_modified=false;
    OUT.status='INSTALL_FAILED__ROLLBACK_ATTEMPTED';
    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier = %s',ME.identifier);
    say(fid,' message    = %s',ME.message);
    say(fid,' rollback   = %d',OUT.rollback_performed);
end

OUT.report_path=report;
OUT.mat_path=matp;
